from pathlib import Path
import json,xml.etree.ElementTree as ET,re
R=Path(__file__).resolve().parents[1];m=json.loads((R/'src/dal/models/relational/dictionary.json').read_text())
r=ET.parse(R/'src/dal/models/er/Retail-Mesh-crows-foot-ER.drawio');cells={c.get('id'):c for c in r.iter('mxCell')}
links={'AccountA':'CustomerIdentityLink.AccountAId','AccountB':'CustomerIdentityLink.AccountBId','HasEventBenefit':'EventAwardComponent.EventAwardId + EventAward.FirstComponentId (minimum)','HasPeriodBenefit':'PeriodAwardComponent.PeriodAwardId + PeriodAward.FirstComponentId (minimum)','ContributesTo':'MeasurementContribution','RequiresMetric':'RuleMetric','UsedByEvent':'EventEvaluationMeasurement','UsedByPeriod':'PeriodEvaluationMeasurement','CitedByEvent':'EventEvaluationActivity','CitedByPeriod':'PeriodEvaluationActivity','IdentityForEvent':'EventEvaluationIdentity','IdentityForPeriod':'PeriodEvaluationIdentity','ReplacementFor':'Rental.ReplacementForServiceId + ReplacementPurpose','AcceptedForEvent':'EventAward.AcceptedEvaluationId (UNIQUE)','AcceptedForPeriod':'PeriodAward.AcceptedEvaluationId (UNIQUE)'}
counts={'ERmandOne':'1..1','ERzeroToOne':'0..1','ERzeroToMany':'0..N','ERoneToMany':'1..N'}
s=['# Complete relationship mapping','', 'Authority: the newly attached ER ZIP, not the old diagram in the repository. Endpoint notation describes instances at the named entity.','', '| Relationship | Endpoints in submitted ER | Implementation |','|---|---|---|']
for k,c in cells.items():
 if not c.get('style','').startswith('rhombus;') or not c.get('value'):continue
 name=c.get('value');ends=[]
 for x in cells.values():
  if x.get('edge')=='1' and x.get('source') in m and x.get('target')==k:
   marker=re.search(r'startArrow=([^;]+)',x.get('style',''))[1];ends.append((x.get('source'),counts[marker]))
 impl=links.get(name)
 if not impl and len(ends)==2:
  for t,_ in ends:
   for col,target in m[t]['fks'].items():
    if target in [e[0] for e in ends] and target!=t:impl=f'{t}.{col}';break
   if impl:break
 s.append('| '+name+' | '+'; '.join(t+' '+n for t,n in ends)+' | '+(impl or 'See full dictionary / schema')+' |')
s+=['','The total, disjoint ISA is implemented with mandatory exactly-one subtype pointers and deferred composite foreign keys; each subtype has its own autogenerated Id and UNIQUE VehicleActivityId. Awards similarly require an owned first component, preserving the 1..N benefit minimum.','', '## Full dictionary','', 'Every relation has Id INTEGER PRIMARY KEY AUTOINCREMENT. CK columns are NOT NULL + UNIQUE. FK enforcement is enabled on each connection; deletes do not cascade. ? marks nullable. Intervals are half-open [start,end), with NULL end meaning unbounded.']
for t,v in m.items():
 s+=['',f'### {t}',', '.join(['Id']+[x+('?' if x in v['optional'] else '') for x in v['fields']]),'', 'CK: '+', '.join(v['ck'])+'.','FK: '+'; '.join(c+' → '+target+'.Id' for c,target in v['fks'].items())+'.']
 if v['checks']:s+=['CHECK: '+'; '.join(v['checks'])+'.']
 if v['unique']:s+=['Additional UNIQUE: '+'; '.join(', '.join(x) for x in v['unique'])+'.']
(R/'doc/relational-mapping.md').write_text('\n'.join(s)+'\n')
